<?php
namespace Tests\Feature;
use Tests\TestCase;use App\Domain\AI\Agents\Enums\{AgentStatus,AgentType,AgentVersionStatus};use App\Domain\AI\Agents\Models\{Agent,AgentVersion};use App\Domain\AI\Knowledge\Data\KnowledgeContentData;use App\Domain\AI\Knowledge\Enums\{KnowledgeVersionStatus};use App\Domain\AI\Knowledge\Models\{AgentVersionKnowledgeSource,KnowledgeSource,KnowledgeSourceVersion};use App\Domain\AI\Knowledge\Services\{ApproveKnowledgeVersionService,AttachKnowledgeToAgentVersionService,CreateKnowledgeRevisionService,CreateKnowledgeSourceService,DetachKnowledgeFromAgentVersionService};use App\Domain\AI\Support\CanonicalJsonHasher;use App\Domain\AI\Support\Exceptions\AiImmutableAttributeException;use App\Domain\Network\Billing\Models\{Entitlement,Subscription};use App\Domain\Network\Catalog\Models\{Module,Plan};use App\Domain\Network\Tenancy\Models\{Tenant,TenantDomain,TenantMembership};use App\Domain\Network\Tenancy\TenantContext;use App\Models\User;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\{DB,Schema};
final class AiKnowledgeFoundationTest extends TestCase{
 protected function setUp():void{parent::setUp();config(['database.default'=>'sqlite','database.connections.sqlite.database'=>':memory:','ai.enabled'=>true,'ai.entitlement.module_code'=>'AI_CORE']);$this->schema();app(TenantContext::class)->clear();}
 public function test_manual_and_faq_create_version_one_with_canonical_checksum():void{[$t,$u]=$this->authorized('create');foreach([KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'  Horario de lunes a viernes.  ']),KnowledgeContentData::fromArray(['type'=>'faq','entries'=>[['question'=>' ¿Horario? ','answer'=>' De 9 a 18. ']]])]as$i=>$data){$s=app(CreateKnowledgeSourceService::class)->create($u,'Fuente '.$i,$data);$v=$s->versions->first();$this->assertSame(1,$v->version_number);$this->assertSame(KnowledgeVersionStatus::Draft,$v->status);$this->assertSame(app(CanonicalJsonHasher::class)->hash($v->content),$v->checksum);$this->assertSame($t->id,$v->tenant_id);} }
 public function test_approval_revision_supersedes_but_existing_attachment_stays_pinned():void{[$t,$u]=$this->authorized('version');$source=app(CreateKnowledgeSourceService::class)->create($u,'FAQ',$this->faq('Uno'));$v1=$source->versions->first();app(ApproveKnowledgeVersionService::class)->approve($u,$v1);[$agent,$av]=$this->agent($u);$link=app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v1);$v2=app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Dos'));$this->assertSame(2,$v2->version_number);app(ApproveKnowledgeVersionService::class)->approve($u,$v2);$this->assertSame(KnowledgeVersionStatus::Superseded,$v1->fresh()->status);$this->assertSame(KnowledgeVersionStatus::Approved,$v2->fresh()->status);$this->assertSame($v1->id,$link->fresh()->knowledge_source_version_id);}
 public function test_attach_is_idempotent_detach_is_idempotent_and_never_changes_configuration():void{[$t,$u]=$this->authorized('attach');$source=app(CreateKnowledgeSourceService::class)->create($u,'Manual',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato']));$v=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());[$agent,$av]=$this->agent($u);$before=$av->configuration;$one=app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v);$two=app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v);$this->assertTrue($one->is($two));$this->assertSame(1,AgentVersionKnowledgeSource::count());app(DetachKnowledgeFromAgentVersionService::class)->detach($u,$agent,$v);app(DetachKnowledgeFromAgentVersionService::class)->detach($u,$agent,$v);$this->assertSame(0,AgentVersionKnowledgeSource::count());$this->assertSame($before,$av->fresh()->configuration);}
 public function test_attach_requires_approved_knowledge_and_draft_agent_version():void{[$t,$u]=$this->authorized('guards');$source=app(CreateKnowledgeSourceService::class)->create($u,'Manual',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato']));[$agent,$av]=$this->agent($u);try{app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$source->versions->first());$this->fail();}catch(\DomainException){}DB::table('ai_knowledge_source_versions')->where('id',$source->versions->first()->id)->update(['status'=>'approved']);DB::table('ai_agent_versions')->where('id',$av->id)->update(['status'=>'testing']);$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$source->versions->first()->fresh());}
 public function test_content_rejects_html_controls_unexpected_ids_and_sensitive_keys():void{foreach([['type'=>'manual_text','body'=>'<script>x</script>'],['type'=>'manual_text','body'=>"bad\x01"],['type'=>'manual_text','body'=>'ok','tenant_id'=>1],['type'=>'faq','entries'=>[['question'=>'Q','answer'=>'A','token'=>'x']]],['type'=>'faq','entries'=>[]]]as$p){try{KnowledgeContentData::fromArray($p);$this->fail();}catch(\InvalidArgumentException){$this->addToAssertionCount(1);}}}
 public function test_sources_versions_and_links_block_direct_mutation_bulk_and_delete():void{[$t,$u]=$this->authorized('immutable');$source=app(CreateKnowledgeSourceService::class)->create($u,'Manual',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato']));$v=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());foreach([function()use($source){$source->name='Otro';$source->saveQuietly();},fn()=>KnowledgeSource::query()->update(['name'=>'Otro']),fn()=>KnowledgeSourceVersion::query()->insert([['x'=>1]]),fn()=>$v->delete()]as$attempt){try{$attempt();$this->fail();}catch(AiImmutableAttributeException){$this->addToAssertionCount(1);}}}
 public function test_tenant_scope_and_database_constraints_reject_cross_tenant():void{[$a,$ua]=$this->authorized('a');$source=app(CreateKnowledgeSourceService::class)->create($ua,'A',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'A']));[$b,$ub]=$this->authorized('b');$this->assertNull(KnowledgeSource::find($source->id));[$agentB,$avB]=$this->agent($ub);try{DB::table('ai_agent_version_knowledge_sources')->insert(['tenant_id'=>$b->id,'agent_version_id'=>$avB->id,'knowledge_source_id'=>$source->id,'knowledge_source_version_id'=>$source->versions->first()->id,'attached_by_user_id'=>$ub->id,'created_at'=>now(),'updated_at'=>now()]);$this->fail();}catch(\Illuminate\Database\QueryException){$this->assertSame(0,DB::table('ai_agent_version_knowledge_sources')->count());}}
 public function test_http_flow_authorization_validation_xss_and_cross_tenant():void{[$t,$u]=$this->httpTenant('http','owner');$base='http://http.test';$this->actingAs($u)->get($base.'/admin/ai-knowledge')->assertOk()->assertSee('Conocimiento');$this->post($base.'/admin/ai-knowledge',['name'=>'FAQ segura','type'=>'faq','entries'=>[['question'=>'Pregunta','answer'=>'Respuesta']]])->assertRedirect();$source=KnowledgeSource::firstOrFail();$version=$source->versions()->firstOrFail();$this->post($base.'/admin/ai-knowledge/'.$source->uuid.'/versions/'.$version->uuid.'/approve')->assertRedirect();[$agent]=$this->agent($u);$this->post($base.'/admin/ai-agents/'.$agent->id.'/knowledge/'.$version->uuid)->assertRedirect();$this->get($base.'/admin/ai-agents/'.$agent->id)->assertOk()->assertSee('Conocimiento configurado')->assertSee('FAQ segura');$this->post($base.'/admin/ai-knowledge',['name'=>'X','type'=>'manual_text','body'=>'<script>alert(1)</script>'])->assertSessionHasErrors();$this->post($base.'/admin/ai-knowledge',['name'=>'X','type'=>'manual_text','body'=>'ok','tenant_id'=>9])->assertSessionHasErrors('tenant_id');$viewer=$this->user('viewer@http.test');$this->membership($t,$viewer,'viewer');$this->actingAs($viewer)->get($base.'/admin/ai-knowledge')->assertForbidden();$this->assertSame(1,KnowledgeSource::count());}
 public function test_http_roles_gates_guest_and_cross_tenant_fail_closed():void{[$a,$owner]=$this->httpTenant('secure-a','owner');app(TenantContext::class)->set($a);$source=app(CreateKnowledgeSourceService::class)->create($owner,'Privada',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato privado']));foreach(['viewer','operator','support','billing']as$role){$actor=$this->user($role.'@secure.test');$this->membership($a,$actor,$role);$this->actingAs($actor)->get('http://secure-a.test/admin/ai-knowledge')->assertForbidden();}$suspended=$this->user('suspended@secure.test');$membership=$this->membership($a,$suspended,'admin');$membership->status='suspended';$membership->save();$this->actingAs($suspended)->get('http://secure-a.test/admin/ai-knowledge')->assertRedirect();[$b,$admin]=$this->httpTenant('secure-b','admin');$this->actingAs($admin)->get('http://secure-b.test/admin/ai-knowledge/'.$source->uuid)->assertNotFound();$this->actingAs($admin)->post('http://secure-b.test/admin/ai-knowledge/'.$source->uuid.'/versions/'.$source->versions->first()->uuid.'/approve')->assertNotFound();auth()->logout();$this->get('http://secure-a.test/admin/ai-knowledge')->assertRedirect();config(['ai.enabled'=>false]);$this->actingAs($owner)->get('http://secure-a.test/admin/ai-knowledge')->assertNotFound();config(['ai.enabled'=>true]);$this->assertSame(1,DB::table('ai_knowledge_sources')->count());}
 public function test_attach_replaces_version_for_same_source_and_preserves_other_agent_history():void{[$t,$u]=$this->authorized('replace');$source=app(CreateKnowledgeSourceService::class)->create($u,'FAQ',$this->faq('Uno'));$v1=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());[$agent1,$av1]=$this->agent($u);[$agent2,$av2]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent1,$v1);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent2,$v1);$v2=app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Dos'));$v2=app(ApproveKnowledgeVersionService::class)->approve($u,$v2);$link=app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent1,$v2);$again=app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent1,$v2);$this->assertTrue($link->is($again));$this->assertSame(1,AgentVersionKnowledgeSource::where('agent_version_id',$av1->id)->where('knowledge_source_id',$source->id)->count());$this->assertDatabaseHas('ai_agent_version_knowledge_sources',['agent_version_id'=>$av1->id,'knowledge_source_id'=>$source->id,'knowledge_source_version_id'=>$v2->id]);$this->assertDatabaseHas('ai_agent_version_knowledge_sources',['agent_version_id'=>$av2->id,'knowledge_source_version_id'=>$v1->id]);$this->assertSame(KnowledgeVersionStatus::Superseded,$v1->fresh()->status);$this->assertSame(1,KnowledgeSourceVersion::where('knowledge_source_id',$source->id)->where('status','approved')->count());}
 public function test_database_and_model_enforce_source_version_attachment_identity():void{[$t,$u]=$this->authorized('physical');$one=app(CreateKnowledgeSourceService::class)->create($u,'Uno',$this->faq('Uno'));$v1=app(ApproveKnowledgeVersionService::class)->approve($u,$one->versions->first());$v2=app(ApproveKnowledgeVersionService::class)->approve($u,app(CreateKnowledgeRevisionService::class)->create($u,$one,$this->faq('Dos')));$other=app(CreateKnowledgeSourceService::class)->create($u,'Otra',$this->faq('Otra'));$otherVersion=app(ApproveKnowledgeVersionService::class)->approve($u,$other->versions->first());[$agent,$av]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v2);foreach([['tenant_id'=>$t->id,'agent_version_id'=>$av->id,'knowledge_source_id'=>$one->id,'knowledge_source_version_id'=>$v1->id,'attached_by_user_id'=>$u->id],['tenant_id'=>$t->id,'agent_version_id'=>$av->id,'knowledge_source_id'=>$one->id,'knowledge_source_version_id'=>$otherVersion->id,'attached_by_user_id'=>$u->id]]as$values){try{DB::table('ai_agent_version_knowledge_sources')->insert($values+['created_at'=>now(),'updated_at'=>now()]);$this->fail('Attachment constraint must reject invalid structure.');}catch(\Illuminate\Database\QueryException){$this->assertSame(1,DB::table('ai_agent_version_knowledge_sources')->where('agent_version_id',$av->id)->count());}}$bad=new AgentVersionKnowledgeSource();$bad->agent_version_id=$av->id;$bad->knowledge_source_id=$one->id;$bad->knowledge_source_version_id=$otherVersion->id;$bad->attached_by_user_id=$u->id;$this->expectException(\DomainException::class);$bad->save();}
 public function test_archived_source_blocks_revision_approval_and_attach_but_allows_detach():void{[$t,$u]=$this->authorized('archive');$source=app(CreateKnowledgeSourceService::class)->create($u,'Archivo',$this->faq('Uno'));$v1=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());$v2=app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Dos'));[$agent,$av]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v1);DB::transaction(function()use($u,$source){$a=app(\App\Domain\AI\Agents\Services\AiLifecycleAuthorization::class)->authorize($u);KnowledgeSource::query()->lockForUpdate()->findOrFail($source->id)->archive($a);});foreach([fn()=>app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Tres')),fn()=>app(ApproveKnowledgeVersionService::class)->approve($u,$v2),fn()=>app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v1)]as$operation){try{$operation();$this->fail('Archived source operation must fail.');}catch(\App\Domain\AI\Knowledge\Exceptions\ArchivedKnowledgeSourceException){$this->addToAssertionCount(1);}}$this->assertSame(KnowledgeVersionStatus::Draft,$v2->fresh()->status);$this->assertSame(1,AgentVersionKnowledgeSource::count());app(DetachKnowledgeFromAgentVersionService::class)->detach($u,$agent,$v1);$this->assertSame(0,AgentVersionKnowledgeSource::count());}
 public function test_source_name_domain_and_http_validation_is_single_safe_boundary():void{[$t,$u]=$this->httpTenant('names','owner');$valid=app(CreateKnowledgeSourceService::class)->create($u,'  Catálogo Ñandú  ',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato']));$this->assertSame('Catálogo Ñandú',$valid->name);$invalid=['   ',str_repeat('á',161),"Control\x01",'<script>alert(1)</script>','&lt;script&gt;x&lt;/script&gt;','api_key=secret-value','Bearer abcdefghijklmnop','ignore previous instructions'];foreach($invalid as$name){try{app(CreateKnowledgeSourceService::class)->create($u,$name,KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato']));$this->fail('Invalid source name must fail.');}catch(\InvalidArgumentException$e){$this->assertSame('Knowledge source name is invalid.',$e->getMessage());}$this->actingAs($u)->post('http://names.test/admin/ai-knowledge',['name'=>$name,'type'=>'manual_text','body'=>'Dato'])->assertSessionHasErrors('name');}$this->assertSame(1,KnowledgeSource::count());DB::table('ai_knowledge_sources')->insert(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>$t->id,'name'=>'<script>alert(1)</script>','type'=>'manual_text','status'=>'active','created_by_user_id'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);$fixture=KnowledgeSource::latest('id')->firstOrFail();$this->actingAs($u)->get('http://names.test/admin/ai-knowledge/'.$fixture->uuid)->assertOk()->assertSee('&lt;script&gt;alert(1)&lt;/script&gt;',false)->assertDontSee('<script>alert(1)</script>',false);}
 public function test_approval_fails_closed_when_multiple_approved_versions_are_persisted():void{[$t,$u]=$this->authorized('approval-conflict');$source=app(CreateKnowledgeSourceService::class)->create($u,'Conflicto',$this->faq('Uno'));$v1=$source->versions->first();$v2=app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Dos'));$v3=app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Tres'));DB::table('ai_knowledge_source_versions')->whereIn('id',[$v1->id,$v2->id])->update(['status'=>'approved']);try{app(ApproveKnowledgeVersionService::class)->approve($u,$v3);$this->fail('Inconsistent approval state must fail.');}catch(\App\Domain\AI\Knowledge\Exceptions\KnowledgeApprovalConflictException){$this->assertSame('draft',$v3->fresh()->status->value);$this->assertSame(2,KnowledgeSourceVersion::where('knowledge_source_id',$source->id)->where('status','approved')->count());}}
 public function test_constraint_classifier_only_recognizes_named_unique_collisions():void{$revision=new \Illuminate\Database\QueryException('sqlite','insert',[],new \PDOException('UNIQUE constraint failed: ai_knowledge_source_versions.tenant_id, ai_knowledge_source_versions.knowledge_source_id, ai_knowledge_source_versions.version_number',23000));$unrelated=new \Illuminate\Database\QueryException('sqlite','insert',[],new \PDOException('FOREIGN KEY constraint failed',23000));$this->assertTrue(\App\Domain\AI\Knowledge\Support\KnowledgeConstraintClassifier::isRevisionNumberCollision($revision));$this->assertFalse(\App\Domain\AI\Knowledge\Support\KnowledgeConstraintClassifier::isRevisionNumberCollision($unrelated));$this->assertFalse(\App\Domain\AI\Knowledge\Support\KnowledgeConstraintClassifier::isAttachmentSourceCollision($unrelated));}
 public function test_migration_has_composite_identity_unique_foreign_keys_and_restrict():void{$columns=collect(Schema::getColumns('ai_agent_version_knowledge_sources'))->pluck('name');$this->assertContains('knowledge_source_id',$columns);$indexes=collect(DB::select("PRAGMA index_list('ai_agent_version_knowledge_sources')"))->pluck('name');$this->assertContains('ai_agent_knowledge_source_uq',$indexes);$foreign=collect(DB::select("PRAGMA foreign_key_list('ai_agent_version_knowledge_sources')"));$this->assertSame(['RESTRICT'],array_values(array_unique($foreign->pluck('on_delete')->all())));$this->assertSame(3,$foreign->where('table','ai_knowledge_source_versions')->count());$this->assertSame(2,$foreign->where('table','ai_knowledge_sources')->count());$versionIndexes=collect(DB::select("PRAGMA index_list('ai_knowledge_source_versions')"))->pluck('name');$this->assertContains('ai_knowledge_versions_source_id_uq',$versionIndexes);}
 public function test_http_and_service_gate_failures_do_not_persist():void{[$tenant,$owner]=$this->httpTenant('gates','owner');$base='http://gates.test';$payload=['name'=>'Bloqueada','type'=>'manual_text','body'=>'Dato'];$staff=$this->user('staff@gates.test');$this->membership($tenant,$staff,'staff');$this->actingAs($staff)->post($base.'/admin/ai-knowledge',$payload)->assertForbidden();$external=$this->user('external@gates.test');app(TenantContext::class)->set($tenant);try{app(CreateKnowledgeSourceService::class)->create($external,'Externa',KnowledgeContentData::fromArray(['type'=>'manual_text','body'=>'Dato']));$this->fail('External actor must fail.');}catch(\Illuminate\Auth\Access\AuthorizationException){$this->assertSame(0,KnowledgeSource::count());}config(['ai.enabled'=>false]);$this->actingAs($owner)->post($base.'/admin/ai-knowledge',$payload)->assertNotFound();config(['ai.enabled'=>true]);DB::table('network_entitlements')->where('tenant_id',$tenant->id)->delete();$this->actingAs($owner)->post($base.'/admin/ai-knowledge',$payload)->assertForbidden();$this->assertSame(0,KnowledgeSource::count());}
 public function test_inactive_tenant_and_missing_subscription_fail_closed():void{$inactive=$this->tenant('inactive');$inactive->status='inactive';$inactive->save();$owner=$this->user('inactive@test');$this->membership($inactive,$owner,'owner');TenantDomain::create(['tenant_id'=>$inactive->id,'domain'=>'inactive.test','type'=>'subdomain','environment'=>'sandbox','is_primary'=>true,'status'=>'verified','verified_at'=>now()]);$this->actingAs($owner)->get('http://inactive.test/admin/ai-knowledge')->assertNotFound();$plain=$this->tenant('no-sub');$plainOwner=$this->user('no-sub@test');$this->membership($plain,$plainOwner,'owner');TenantDomain::create(['tenant_id'=>$plain->id,'domain'=>'no-sub.test','type'=>'subdomain','environment'=>'sandbox','is_primary'=>true,'status'=>'verified','verified_at'=>now()]);$this->actingAs($plainOwner)->get('http://no-sub.test/admin/ai-knowledge')->assertForbidden();$this->assertSame(0,KnowledgeSource::count());}
 public function test_all_non_draft_agent_version_states_reject_attach_and_detach():void{[$t,$u]=$this->authorized('non-draft');$source=app(CreateKnowledgeSourceService::class)->create($u,'Estados',$this->faq('Uno'));$version=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());foreach(['testing','approved','published','retired']as$status){[$agent,$av]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$version);DB::table('ai_agent_versions')->where('id',$av->id)->update(['status'=>$status]);foreach([fn()=>app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$version),fn()=>app(DetachKnowledgeFromAgentVersionService::class)->detach($u,$agent,$version)]as$operation){try{$operation();$this->fail('Non-draft Agent Version mutation must fail.');}catch(\Illuminate\Database\Eloquent\ModelNotFoundException){$this->assertDatabaseHas('ai_agent_version_knowledge_sources',['agent_version_id'=>$av->id,'knowledge_source_version_id'=>$version->id]);}}}}
 public function test_all_generic_write_paths_are_blocked_for_each_knowledge_model():void{[$t,$u]=$this->authorized('write-matrix');$source=app(CreateKnowledgeSourceService::class)->create($u,'Matriz',$this->faq('Uno'));$version=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());[$agent]=$this->agent($u);$link=app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$version);foreach([[KnowledgeSource::class,$source->id],[KnowledgeSourceVersion::class,$version->id],[AgentVersionKnowledgeSource::class,$link->id]]as[$class,$id]){$this->assertImmutable(fn()=>tap($class::findOrFail($id),fn($m)=>$m->tenant_id=999)->save());$this->assertImmutable(fn()=>tap($class::findOrFail($id),fn($m)=>$m->tenant_id=999)->saveQuietly());$this->assertImmutable(fn()=>$class::query()->whereKey($id)->update(['tenant_id'=>999]));$this->assertImmutable(fn()=>$class::query()->increment('id'));$this->assertImmutable(fn()=>$class::query()->decrement('id'));$this->assertImmutable(fn()=>$class::query()->insert([['tenant_id'=>$t->id]]));$this->assertImmutable(fn()=>$class::query()->insertOrIgnore([['tenant_id'=>$t->id]]));$this->assertImmutable(fn()=>$class::query()->insertGetId(['tenant_id'=>$t->id]));$this->assertImmutable(fn()=>$class::query()->upsert([['tenant_id'=>$t->id]],['tenant_id']));$this->assertImmutable(fn()=>$class::findOrFail($id)->delete());$this->assertImmutable(fn()=>$class::findOrFail($id)->deleteQuietly());$this->assertImmutable(fn()=>$class::query()->whereKey($id)->delete());$this->assertImmutable(fn()=>$class::destroy($id));$this->assertImmutable(fn()=>$class::query()->forceDelete());$this->assertImmutable(fn()=>$class::query()->truncate());$this->assertDatabaseHas((new$class)->getTable(),['id'=>$id,'tenant_id'=>$t->id]);}}
 public function test_attach_replace_and_detach_leave_agent_configuration_and_contract_bytes_unchanged():void{[$t,$u]=$this->authorized('aggregate-bytes');$source=app(CreateKnowledgeSourceService::class)->create($u,'Contrato',$this->faq('Uno'));$v1=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());[$agent,$av]=$this->agent($u);$contractId=DB::table('ai_agent_contracts')->insertGetId(['tenant_id'=>$t->id,'agent_id'=>$agent->id,'status'=>'draft','created_by_user_id'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);$policy=json_encode([]);$contract=['tenant_id'=>$t->id,'agent_contract_id'=>$contractId,'version_number'=>1,'status'=>'draft','job_to_be_done'=>'Atender','objectives'=>$policy,'allowed_capabilities'=>$policy,'prohibited_capabilities'=>$policy,'channels'=>$policy,'knowledge_requirements'=>$policy,'allowed_actions'=>$policy,'handoff_policy'=>$policy,'outcome_policy'=>$policy,'capacity_policy'=>$policy,'sla_policy'=>$policy,'privacy_policy'=>$policy,'pricing_policy'=>$policy,'created_by_user_id'=>$u->id,'created_at'=>now(),'updated_at'=>now()];$contractVersionId=DB::table('ai_agent_contract_versions')->insertGetId($contract);DB::table('ai_agent_versions')->where('id',$av->id)->update(['agent_contract_version_id'=>$contractVersionId]);$beforeVersion=(array)DB::table('ai_agent_versions')->where('id',$av->id)->first();$beforeContract=(array)DB::table('ai_agent_contract_versions')->where('id',$contractVersionId)->first();app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v1);$v2=app(ApproveKnowledgeVersionService::class)->approve($u,app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Dos')));app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v2);app(DetachKnowledgeFromAgentVersionService::class)->detach($u,$agent,$v2);$this->assertSame($beforeVersion,(array)DB::table('ai_agent_versions')->where('id',$av->id)->first());$this->assertSame($beforeContract,(array)DB::table('ai_agent_contract_versions')->where('id',$contractVersionId)->first());}
 public function test_failed_replacement_rolls_back_detach_and_preserves_original_link():void{[$t,$u]=$this->authorized('replace-rollback');$source=app(CreateKnowledgeSourceService::class)->create($u,'Rollback',$this->faq('Uno'));$v1=app(ApproveKnowledgeVersionService::class)->approve($u,$source->versions->first());[$agent,$av]=$this->agent($u);app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v1);$v2=app(ApproveKnowledgeVersionService::class)->approve($u,app(CreateKnowledgeRevisionService::class)->create($u,$source,$this->faq('Dos')));AgentVersionKnowledgeSource::creating(function($link)use($v2){if((int)$link->knowledge_source_version_id===(int)$v2->id)throw new \RuntimeException('link failure');});try{app(AttachKnowledgeToAgentVersionService::class)->attach($u,$agent,$v2);$this->fail('Replacement failure expected.');}catch(\RuntimeException$e){$this->assertSame('link failure',$e->getMessage());}$this->assertDatabaseHas('ai_agent_version_knowledge_sources',['agent_version_id'=>$av->id,'knowledge_source_id'=>$source->id,'knowledge_source_version_id'=>$v1->id]);$this->assertDatabaseMissing('ai_agent_version_knowledge_sources',['agent_version_id'=>$av->id,'knowledge_source_version_id'=>$v2->id]);}
 public function test_migration_up_down_up_keeps_foreign_keys_enabled():void{$m=$this->knowledgeMigration();$this->assertSame(1,(int)DB::selectOne('PRAGMA foreign_keys')->foreign_keys);foreach(['ai_knowledge_sources','ai_knowledge_source_versions','ai_agent_version_knowledge_sources']as$table)$this->assertTrue(Schema::hasTable($table));$m->down();$this->assertSame(1,(int)DB::selectOne('PRAGMA foreign_keys')->foreign_keys);$m->up();$this->assertSame(1,(int)DB::selectOne('PRAGMA foreign_keys')->foreign_keys);$this->assertNotEmpty(DB::select("PRAGMA foreign_key_list('ai_agent_version_knowledge_sources')"));}
